(function(){'use strict';
var $=function(id){return document.getElementById(id)},video=$('video'),hls=null,current=null,items=[],attempt=0,loadTimer=null,opener=null;
function validUrl(raw){var u=new URL(raw);if(u.protocol!=='https:')throw Error('HTTPS နဲ့စတဲ့ တိုက်ရိုက် video link ထည့်ပါ။');if(u.username||u.password)throw Error('Username/password ပါတဲ့ link ကို မသိမ်းနိုင်ပါ။');return u.href;}
try{var saved=JSON.parse(localStorage.getItem('luma-streams')||'[]');if(Array.isArray(saved))items=saved.filter(function(s){try{return typeof s.name==='string'&&typeof s.id==='string'&&!!validUrl(s.url)}catch(e){return false}}).slice(0,100)}catch(e){}
function persist(){try{localStorage.setItem('luma-streams',JSON.stringify(items))}catch(e){$('status').textContent='ဒီ browser မှာ သိမ်းမရပါ။ လက်ရှိ session အတွင်းပဲ ရှိပါမယ်။'}}
function render(){var list=$('streams');list.textContent='';$('count').textContent=String(items.length).padStart(2,'0');$('empty').hidden=items.length>0;items.forEach(function(s){var card=document.createElement('div');card.className='stream';var b=document.createElement('button');b.className='open';var strong=document.createElement('strong');strong.textContent='▶  '+s.name;var small=document.createElement('small');small.textContent=new URL(s.url).hostname;b.append(strong,small);b.onclick=function(){start(s,true)};var del=document.createElement('button');del.className='remove';del.textContent='×';del.setAttribute('aria-label','Remove '+s.name);del.onclick=function(){items=items.filter(function(x){return x.id!==s.id});persist();render();$('add').focus()};card.append(b,del);list.append(card)})}
function openDialog(){opener=document.activeElement;$('form-error').textContent='';if(typeof $('dialog').showModal==='function')$('dialog').showModal();else $('dialog').setAttribute('open','');$('url').focus()}
function closeDialog(){if(typeof $('dialog').close==='function')$('dialog').close();else $('dialog').removeAttribute('open');if(opener)opener.focus()}
function fail(message){clearTimeout(loadTimer);$('error-text').textContent=message;$('error').hidden=false;$('status').textContent='Playback unavailable';$('play-state').textContent='UNABLE TO PLAY';}
function playVideo(){var p=video.play();if(p&&p.catch)p.catch(function(e){if(e.name==='NotAllowedError')$('status').textContent='Play သို့မဟုတ် remote OK ကို နှိပ်ပါ။';else if(e.name!=='AbortError')fail('ဒီ video format ကို TV က မဖွင့်နိုင်ပါ၊ ဒါမှမဟုတ် link မရတော့ပါ။')})}
function start(s,autoplay){attempt++;var thisAttempt=attempt;current=s;clearTimeout(loadTimer);if(hls){hls.destroy();hls=null}video.pause();video.removeAttribute('src');video.load();$('idle').hidden=true;$('error').hidden=true;$('screen').classList.add('active');$('watch-title').textContent=s.name;$('detail').textContent=s.demo?'Demo video · Big Buck Bunny':new URL(s.url).hostname;$('play-state').textContent='LOADING';$('status').textContent='ဖွင့်နေပါတယ်…';$('play').disabled=false;$('full').disabled=false;video.onloadedmetadata=function(){if(thisAttempt!==attempt)return;clearTimeout(loadTimer);$('play-state').textContent=Number.isFinite(video.duration)?'READY TO WATCH':'LIVE STREAM';$('status').textContent='';if(autoplay)playVideo()};loadTimer=setTimeout(function(){if(video.readyState<2)fail('Stream မရောက်လာသေးပါ။ Link နဲ့ internet connection ကို စစ်ပြီး ပြန်ဖွင့်ပါ။')},25000);
if(/\.m3u8(?:[?#]|$)/i.test(s.url)&&!video.canPlayType('application/vnd.apple.mpegurl')){if(window.Hls&&Hls.isSupported()){hls=new Hls({maxBufferLength:30});hls.loadSource(s.url);hls.attachMedia(video);hls.on(Hls.Events.ERROR,function(e,data){if(data.fatal&&thisAttempt===attempt)fail('Stream ကို မဖွင့်နိုင်ပါ။ Link သက်တမ်းကုန်တာ၊ CORS ပိတ်ထားတာ၊ format မကိုက်တာ ဖြစ်နိုင်ပါတယ်။')})}else fail('ဒီ browser မှာ HLS stream မရပါ။ MP4 link နဲ့ စမ်းကြည့်ပါ။')}else{video.src=s.url;video.load()}video.focus();return{name:s.name,status:'loading'};}
$('add').onclick=openDialog;$('close').onclick=closeDialog;$('edit-link').onclick=openDialog;
$('form').onsubmit=function(e){e.preventDefault();try{var url=validUrl($('url').value.trim()),name=$('name').value.trim()||'My stream',s={id:Date.now().toString(36),url:url,name:name};if($('save').checked){if(items.length>=100)throw Error('Stream 100 ခု ပြည့်နေပါပြီ။ အဟောင်းတစ်ခု ဖယ်ပြီး ထပ်ထည့်ပါ။');var existing=items.find(function(x){return x.url===url});if(existing)existing.name=name;else items.push(s);persist();render()}closeDialog();start(s,true);$('form').reset()}catch(err){$('form-error').textContent=err.message}};
$('demo').onclick=function(){start({name:'Big Buck Bunny',url:'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8',demo:true},true)};
$('retry').onclick=function(){if(current)start(current,true)};$('play').onclick=function(){if(video.paused)playVideo();else video.pause()};
$('full').onclick=function(){try{var p;if(video.requestFullscreen)p=video.requestFullscreen();else if(video.webkitEnterFullscreen)video.webkitEnterFullscreen();else if(video.webkitRequestFullscreen)video.webkitRequestFullscreen();else{$('status').textContent='ဒီ browser မှာ Fullscreen မရပါ။';return}if(p&&p.catch)p.catch(function(){$('status').textContent='Video controls ထဲက fullscreen ကို စမ်းပါ။'})}catch(e){$('status').textContent='Video controls ထဲက fullscreen ကို စမ်းပါ။'}};
video.onplaying=function(){clearTimeout(loadTimer);$('error').hidden=true;$('status').textContent='';$('play-state').textContent=Number.isFinite(video.duration)?'NOW PLAYING':'LIVE STREAM';$('play').textContent='Ⅱ Pause'};video.onpause=function(){$('play').textContent='▶ Play';if(current)$('play-state').textContent='PAUSED'};video.onwaiting=function(){if(current)$('status').textContent='Buffering…'};video.onended=function(){$('play-state').textContent='FINISHED';$('status').textContent=''};video.onerror=function(){if(current&&video.getAttribute('src'))fail('Video link ကို ဖွင့်မရပါ။ တိုက်ရိုက် link ဖြစ်မဖြစ်နဲ့ TV က format ကို လက်ခံမခံ စစ်ပါ။')};
function focusMove(key){var root=$('dialog').hasAttribute('open')?$('dialog'):document;var nodes=Array.from(root.querySelectorAll('button:not(:disabled),a,input,video')).filter(function(el){return el.getClientRects().length&&el.offsetWidth>0});var active=document.activeElement;if(!nodes.includes(active)){if(nodes[0])nodes[0].focus();return}var a=active.getBoundingClientRect(),ax=a.x+a.width/2,ay=a.y+a.height/2,best=null,score=Infinity;nodes.forEach(function(el){if(el===active)return;var b=el.getBoundingClientRect(),dx=b.x+b.width/2-ax,dy=b.y+b.height/2-ay;var main=(key==='ArrowRight'?dx:key==='ArrowLeft'?-dx:key==='ArrowDown'?dy:-dy),cross=(key==='ArrowRight'||key==='ArrowLeft')?Math.abs(dy):Math.abs(dx);if(main>5){var value=main+cross*3;if(value<score){score=value;best=el}}});if(best)best.focus()}
document.addEventListener('keydown',function(e){var active=document.activeElement;if(e.key==='Escape'||e.keyCode===461){if($('dialog').hasAttribute('open')){e.preventDefault();closeDialog()}return}if(active&&active.tagName==='INPUT')return;if(e.key==='Enter'&&active===video){e.preventDefault();$('play').click();return}if(/^Arrow/.test(e.key)){e.preventDefault();focusMove(e.key)}});
function clock(){$('clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}clock();setInterval(clock,60000);render();$('add').focus();
if(document.modelContext&&document.modelContext.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'play_stream',description:'Start playback of an HTTPS video URL without saving it.',inputSchema:{type:'object',properties:{url:{type:'string'},name:{type:'string'}},required:['url'],additionalProperties:false},annotations:{readOnlyHint:false},execute:function(input){if(!input||typeof input.url!=='string'||(input.name!==undefined&&typeof input.name!=='string'))throw Error('Invalid input');return start({url:validUrl(input.url),name:(input.name||'My stream').slice(0,80)},true)}})).catch(function(){})}catch(e){}}
})();
